// Package quadlet models Quadlet (systemd-style INI) unit files and renders
// them deterministically, with systemd escaping applied.
package quadlet

import (
	"errors"
	"fmt"
	"regexp"
	"strings"
)

// Header is written at the top of every generated file (Principle 4: the
// files are readable, but changes are made through Roostack).
const Header = "# Generated by Roostack. Do not edit: changes will be overwritten.\n"

// Unit is a Quadlet file: ordered sections of ordered key=value entries.
type Unit struct {
	sections []*Section
}

// Section is one [Name] block.
type Section struct {
	Name    string
	entries []entry
}

type entry struct{ key, value string }

// Section returns the named section, creating it at the end if needed.
func (u *Unit) Section(name string) *Section {
	for _, s := range u.sections {
		if s.Name == name {
			return s
		}
	}
	s := &Section{Name: name}
	u.sections = append(u.sections, s)
	return s
}

// Add appends a raw key=value entry. Keys may repeat (e.g. Volume=).
// The value is escaped for systemd specifiers (% becomes %%).
func (s *Section) Add(key, value string) *Section {
	s.entries = append(s.entries, entry{key, strings.ReplaceAll(value, "%", "%%")})
	return s
}

// Env adds an Environment= entry, quoting it when needed.
func (s *Section) Env(name, value string) *Section {
	return s.Add("Environment", Quote(name+"="+value))
}

// Exec adds an Exec= entry from an argument list.
func (s *Section) Exec(args []string) *Section {
	quoted := make([]string, len(args))
	for i, a := range args {
		quoted[i] = Quote(a)
	}
	return s.Add("Exec", strings.Join(quoted, " "))
}

// Validate reports lines that wouldn't be read back as written: a key
// that isn't a plain name, or a value with a line break or a trailing
// backslash (CheckKey, CheckValue). Every unit Roostack writes goes
// through it, so a package's raw lines can't add or hide others (SPEC.md
// §8.3.4).
func (u *Unit) Validate() error {
	for _, s := range u.sections {
		for _, e := range s.entries {
			if err := CheckKey(e.key); err != nil {
				return fmt.Errorf("[%s] %q: %w", s.Name, e.key, err)
			}
			if err := CheckValue(e.value); err != nil {
				return fmt.Errorf("[%s] %s: %w", s.Name, e.key, err)
			}
		}
	}
	return nil
}

// keyRe is a key systemd and Quadlet read exactly as written: letters and
// digits, starting with a letter. Both ignore spaces around a key, so
// "Volume " would be read as Volume, and a key with = or a line break in
// it would be read as another line.
var keyRe = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9]*$`)

// CheckKey says why key can't be written as a unit file key, or nil.
func CheckKey(key string) error {
	if !keyRe.MatchString(key) {
		return errors.New("a key is letters and digits only, starting with a letter")
	}
	return nil
}

// CheckValue says why value can't be written as a unit file value, or
// nil: a line break would start a new line, and a backslash at the end
// joins the next line to this one (both checked on a dev VM with
// Podman 5.4's Quadlet, docs/ASSUMPTIONS.md A12).
func CheckValue(value string) error {
	if strings.ContainsAny(value, "\n\r") {
		return errors.New("value contains a line break")
	}
	if strings.HasSuffix(strings.TrimRight(value, " \t"), `\`) {
		return errors.New("value ends in a backslash, which would join the next line to it")
	}
	return nil
}

// String renders the unit file.
func (u *Unit) String() string {
	var b strings.Builder
	b.WriteString(Header)
	for _, s := range u.sections {
		fmt.Fprintf(&b, "\n[%s]\n", s.Name)
		for _, e := range s.entries {
			fmt.Fprintf(&b, "%s=%s\n", e.key, e.value)
		}
	}
	return b.String()
}

// Quote wraps a word in double quotes (escaping \ and ") when it contains
// characters systemd would otherwise split or interpret.
func Quote(s string) string {
	if s != "" && !strings.ContainsAny(s, " \t\"'\\;") {
		return s
	}
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`)
	return `"` + r.Replace(s) + `"`
}
